def vol_target_leverage(price_panel, weights):
    rets = price_panel.pct_change().tail(VOL_WINDOW)
    pv = float((rets * weights).sum(axis=1).std())       # vol diaria reciente de la cartera
    if pv <= 0 or not np.isfinite(pv):
        return 0.0
    return float(min(MAX_LEVERAGE, (TARGET_VOL / np.sqrt(252)) / pv))

