def sim_day(o, h, l, c, Hlv, Llv, s, sl_mode, tp, allow, mode):
    pos = 0; e = S = T = 0.0; mid = 0.5 * (Hlv + Llv)
    al = allow in ("both", "long"); ash = allow in ("both", "short")
    for i in range(s, NB):                      # velas de 30 min desde que termina el rango (s)
        oi, hi, li, ci = o[i], h[i], l[i], c[i]
        if pos == 0:
            up = al and hi >= Hlv; dn = ash and li <= Llv      # buy stop en el máximo, sell stop en el mínimo
            if not up and not dn: continue
            first_up = (oi >= Hlv) or (oi > Llv and (Hlv - oi) <= (oi - Llv)) if up and dn else up
            # orden intrabarra ADVERSO ('pess'): tras entrar, el extremo desfavorable va antes que el favorable
            if first_up: pts = (oi, li, hi, ci) if oi >= Hlv else (oi, Hlv, li, hi, ci)
            else:        pts = (oi, hi, li, ci) if oi <= Llv else (oi, Llv, hi, li, ci)
        else:
            pts = (oi, li, hi, ci) if pos == 1 else (oi, hi, li, ci)
        x = pts[0]
        for k in range(len(pts) - 1):
            a = pts[k]; b = pts[k + 1]
            if pos == 0:
                if k == 0 and al and a >= Hlv: pos = 1; e = a          # gap: entra a la apertura
                elif b > a and al and a < Hlv <= b: pos = 1; e = Hlv    # cruza el nivel: entra en él
                else: x = b; continue
                S = Llv if sl_mode == "opp" else mid                    # stop: lado opuesto o mitad del rango
                T = e + tp * (e - S) if tp else np.inf                  # objetivo 1:tp (o ninguno)
                x = e
            if pos == 1:
                if b < x:
                    if x <= S: return (1, e, x)
                    if b <= S: return (1, e, S)
                elif b > x:
                    if x >= T: return (1, e, x)
                    if b >= T: return (1, e, T)
            x = b
    return (pos, e, c[NB - 1]) if pos != 0 else None                    # sin salida: cierre de las 16:00
